<script setup lang="ts">
import { computed,ref } from 'vue'
import { ArrowRight, ArrowUpRight, Crosshair, Radio, Shield, Skull, Settings2, PawPrint, Target, Users, Volume2, VolumeX, Maximize, Check, ChevronRight, MapPin, Headphones, HelpCircle, Save, X, Zap, Infinity as InfinityIcon } from '@lucide/vue'
import { loadout,outfits,persistence,records,persist } from '@/stores/profile'
import { ARSENAL,OPERATORS,PALETTE,SKIN_TONES,SLOTS,DISTRICTS,WEAPON_IDS,type Slot } from '@/data/content'
import LobbyStage from '@/components/LobbyStage.vue'
import SpritePreview from '@/components/SpritePreview.vue'
import SettingsPanel from '@/components/SettingsPanel.vue'
const props=defineProps<{ready:boolean;muted:boolean}>()
const emit=defineEmits<{start:[];sound:[];fullscreen:[];configure:[]}>()
const tab=ref('operation'),slot=ref<Slot>('head'),help=ref(false),savedNote=ref('')
const tabs=[{id:'operation',label:'Operación',icon:Crosshair},{id:'operators',label:'Operadores',icon:Users},{id:'arsenal',label:'Arsenal',icon:Target},{id:'companion',label:'Compañero',icon:PawPrint},{id:'settings',label:'Ajustes',icon:Settings2}]
const op=computed(()=>OPERATORS.find(o=>o.id===loadout.operator)||OPERATORS[0]);const weapon=computed(()=>ARSENAL[loadout.weapon]);const piece=computed(()=>loadout.outfit.pieces[slot.value]);const slotInfo=computed(()=>SLOTS.find(s=>s.id===slot.value)!)
function saveOutfit(i:number){outfits[i]=JSON.parse(JSON.stringify(loadout.outfit));persist();savedNote.value=`Conjunto ${i+1} guardado`;setTimeout(()=>savedNote.value='',2400)}
</script>
<template>
 <section class="lobby" data-testid="lobby">
  <header class="lobby-header"><a class="wordmark" href="#" data-testid="brand-home" @click.prevent="tab='operation'"><span class="logo-mark"><Crosshair :size="24" /></span><span>DEAD CITY<small>Ú L T I M A  G U A R D I A</small></span></a><div class="header-edition"><span>OPERACIÓN 09</span><i /> EDICIÓN CINEMATOGRÁFICA</div><div class="header-tools"><span class="local-status"><i class="status-dot" /> MODO LOCAL</span><button data-testid="lobby-help" class="icon-button" aria-label="Cómo jugar" @click="help=true"><HelpCircle /></button><button data-testid="lobby-sound" class="icon-button" :aria-label="props.muted?'Activar sonido':'Silenciar sonido'" @click="emit('sound')"><VolumeX v-if="props.muted"/><Volume2 v-else/></button><button data-testid="lobby-fullscreen" class="icon-button fullscreen" aria-label="Pantalla completa" @click="emit('fullscreen')"><Maximize/></button></div></header>
  <div class="lobby-body">
   <nav class="lobby-rail" aria-label="Secciones del lobby"><button v-for="t in tabs" :key="t.id" :data-testid="`tab-${t.id}`" :class="{active:tab===t.id}" :aria-pressed="tab===t.id" @click="tab=t.id"><component :is="t.icon" :size="21"/><span>{{t.label}}</span><i v-if="tab===t.id"/></button><span class="rail-version">V.3.0</span></nav>
   <div class="lobby-panel" :key="tab">
    <template v-if="tab==='operation'"><div class="section-kicker"><span class="status-dot"/> TRANSMISIÓN RESTABLECIDA</div><h1>VUELVE<br/><em>CON VIDA.</em></h1><p class="operation-copy">La ciudad cayó. Tú todavía no.<br/>Prepara tu equipo. La noche no perdona.</p><div class="section-heading"><span>01 / ELIGE TU MISIÓN</span><span>UN JUGADOR</span></div><div class="mode-options"><button data-testid="mode-campaign" :class="{selected:loadout.mode==='campaign'}" :aria-pressed="loadout.mode==='campaign'" @click="loadout.mode='campaign'"><Shield :size="21"/><span><strong>Extracción</strong><small>10 rondas · Un último coloso</small></span><Check v-if="loadout.mode==='campaign'" :size="16"/></button><button data-testid="mode-infinite" :class="{selected:loadout.mode==='infinite'}" :aria-pressed="loadout.mode==='infinite'" @click="loadout.mode='infinite'"><InfinityIcon :size="22"/><span><strong>Resistencia</strong><small>Oleadas infinitas · Sin rendirse</small></span><Check v-if="loadout.mode==='infinite'" :size="16"/></button></div>
    <div class="section-heading"><span>02 / PUNTO DE INSERCIÓN</span><MapPin :size="13"/></div><div class="district-selector"><button v-for="(d,i) in DISTRICTS" :key="d.code" :data-testid="`district-${i}`" :style="{'--district':d.color}" :class="{selected:loadout.district===i}" :aria-pressed="loadout.district===i" @click="loadout.district=i"><span>{{d.code}}</span><strong>{{d.type}}</strong><i/></button></div><p class="district-description">{{DISTRICTS[loadout.district]?.description}}</p>
    <div class="loadout-summary"><div><span class="tiny-label">OPERADOR</span><b>{{op.name}} <small>/ {{op.role}}</small></b></div><button data-testid="edit-loadout" aria-label="Editar equipamiento" @click="tab='operators'"><ArrowUpRight :size="20"/></button></div></template>
    <template v-else-if="tab==='operators'"><div class="section-kicker">LA PERSONA DETRÁS DEL VISOR</div><h2>Tu operador<span>.</span></h2><p class="muted">Cuatro especialidades. Tu propia identidad.</p><div class="operator-grid"><button v-for="o in OPERATORS" :key="o.id" :data-testid="`operator-${o.id}`" :class="{selected:loadout.operator===o.id}" @click="loadout.operator=o.id" :aria-pressed="loadout.operator===o.id"><SpritePreview :color="o.color" compact/><span>{{o.name}}<small>{{o.role}}</small></span><Check v-if="loadout.operator===o.id" :size="12"/></button></div><div class="perk"><Shield :size="18"/><span><strong>{{op.perk}}</strong><small>{{op.description}}</small></span></div><div class="section-heading"><span>PERSONALIZACIÓN POR PIEZAS</span><span>9 ZONAS</span></div><div class="slot-tabs"><button v-for="s in SLOTS" :key="s.id" :data-testid="`slot-${s.id}`" :class="{selected:slot===s.id}" @click="slot=s.id">{{s.label}}</button></div><label class="piece-label">{{slotInfo.label}}<select :data-testid="`variant-${slot}`" v-model.number="piece.variant"><option v-for="(v,i) in slotInfo.variants" :key="v" :value="i">{{v}}</option></select></label><div class="swatches"><button v-for="(color,i) in PALETTE" :key="color" :data-testid="`piece-color-${i}`" :style="{background:color}" :class="{selected:piece.color===color}" :aria-label="`Color de pieza ${i+1}`" :aria-pressed="piece.color===color" @click="piece.color=color"><Check v-if="piece.color===color" :size="14"/></button></div><label class="tiny-label">TONO DE PIEL</label><div class="swatches skin"><button v-for="(color,i) in SKIN_TONES" :key="color" :data-testid="`skin-tone-${i}`" :style="{background:color}" :class="{selected:loadout.outfit.skin===color}" :aria-label="`Tono de piel ${i+1}`" @click="loadout.outfit.skin=color"><Check v-if="loadout.outfit.skin===color" :size="14"/></button></div><div class="saved-outfits"><div v-for="i in 3" :key="i"><button :data-testid="`load-outfit-${i}`" :disabled="!outfits[i-1]" @click="loadout.outfit=JSON.parse(JSON.stringify(outfits[i-1]))">Conjunto {{i}}</button><button :data-testid="`save-outfit-${i}`" :aria-label="`Guardar conjunto ${i}`" @click="saveOutfit(i-1)"><Save :size="15"/></button></div></div><p class="save-note" role="status">{{savedNote||'Los cambios se guardan en este navegador.'}}</p></template>
    <template v-else-if="tab==='arsenal'"><div class="section-kicker">CADA DISPARO CUENTA</div><h2>El arsenal<span>.</span></h2><p class="muted">Ocho respuestas a la misma amenaza.</p><div class="weapon-grid"><button v-for="id in WEAPON_IDS" :key="id" :data-testid="`equip-${id}`" :aria-pressed="loadout.weapon===id" :class="{selected:loadout.weapon===id}" @click="loadout.weapon=id"><SpritePreview kind="weapon" :weapon="id" compact/><span>{{ARSENAL[id].title.split(' · ')[0]}}<small>{{ARSENAL[id].category}}</small></span><Check v-if="loadout.weapon===id" :size="13"/></button></div><div class="weapon-detail"><span class="section-kicker">EQUIPADA / {{weapon.category}}</span><h3>{{weapon.title}}</h3><p class="muted">{{weapon.description}}</p><dl><div><dt>Daño</dt><dd>{{weapon.damage}}{{weapon.pellets>1?` × ${weapon.pellets}`:''}}</dd></div><div><dt>Cadencia</dt><dd>{{Math.round(60/weapon.interval)}} <small>RPM</small></dd></div><div><dt>Cargador</dt><dd>{{weapon.magazine}}</dd></div><div><dt>Recarga</dt><dd>{{weapon.reload}} <small>s</small></dd></div><div><dt>Alcance</dt><dd>{{weapon.range/10}} <small>m</small></dd></div><div><dt>Retroceso</dt><dd>{{weapon.recoil}}</dd></div></dl><span class="tiny-label">ACABADO DEL ARMA</span><div class="swatches"><button v-for="(color,i) in ['#93a4ad','#b98d65','#426e81','#8582a4','#b3b8a6']" :key="color" :data-testid="`weapon-skin-${i}`" :style="{background:color}" :aria-label="`Acabado ${i+1}`" :class="{selected:loadout.outfit.weaponSkin===color}" @click="loadout.outfit.weaponSkin=color"><Check v-if="loadout.outfit.weaponSkin===color" :size="14"/></button></div></div></template>
    <template v-else-if="tab==='companion'"><div class="section-kicker">NUNCA CAMINAS SOLO</div><h2>Un buen compañero<span>.</span></h2><p class="muted">Leal, atento y siempre de tu lado.</p><div class="companion-card"><SpritePreview kind="dog"/><div><span class="section-kicker">UNIDAD CANINA / K9</span><h3>ATLAS</h3><p>Pastor alemán · Protección cercana</p></div><span class="ready-badge"><span class="status-dot"/> LISTO</span></div><label class="toggle-row companion-toggle"><span>Desplegar con Atlas</span><input v-model="loadout.dog" type="checkbox" data-testid="companion-enabled"/><i aria-hidden="true"/></label><div class="section-heading"><span>RADIO DE PROTECCIÓN</span><Shield :size="14"/></div><div class="segmented"><button v-for="r in ([5,10,15] as const)" :key="r" :data-testid="`dog-radius-${r}`" :class="{selected:loadout.dogRadius===r}" @click="loadout.dogRadius=r">{{r}} metros</button></div><div class="section-heading"><span>ORDEN INICIAL</span><Radio :size="14"/></div><div class="segmented"><button v-for="o in (['follow','defend','attack'] as const)" :key="o" :data-testid="`dog-order-${o}`" :class="{selected:loadout.dogOrder===o}" @click="loadout.dogOrder=o">{{o==='follow'?'Seguir':o==='defend'?'Defender':'Atacar'}}</button></div><p class="settings-note">Seguir: protege tu recorrido. Defender: mantiene una posición. Atacar: amplía su búsqueda al 150% del radio. Puedes cambiar la orden durante el combate.</p><div class="perk"><PawPrint :size="21"/><span><strong>Un vínculo, no una vida extra</strong><small>Si cae, se recupera en 12 s. No hay pérdida permanente.</small></span></div><div class="squad-brief"><Users :size="23"/><div><h3>Equipo Eco</h3><p>Consigue una señal <b>S</b> para convocar a dos aliados durante 25 s. Apoyo garantizado en la ronda final.</p></div></div></template>
    <SettingsPanel v-else @change="emit('configure')"/>
    <div v-if="persistence.error" role="alert" class="save-error">{{persistence.error}}</div>
    <div class="start-dock"><button data-testid="lobby-start" class="primary start-operation" :disabled="!props.ready" @click="emit('start')"><Crosshair :size="20"/><span>{{props.ready?'INICIAR OPERACIÓN':'PREPARANDO ZONA…'}}</span><ArrowRight :size="21"/></button><span class="start-footnote"><kbd>ENTER</kbd> DESPLEGAR <i/> EQUIPO GUARDADO EN ESTE NAVEGADOR</span></div>
   </div>
   <section class="stage-column" data-testid="lobby-canvas-frame"><div class="stage-top"><span><i class="status-dot"/> VISTA EN TIEMPO REAL</span><span>03 DISTRITOS CONECTADOS <i class="stage-dot"/></span></div><div class="stage-art"><LobbyStage/><div class="stage-location"><MapPin :size="13"/><span>{{DISTRICTS[loadout.district]?.type.toUpperCase()}}<strong>{{DISTRICTS[loadout.district]?.name}}</strong></span><span class="location-coordinates">ZONA {{DISTRICTS[loadout.district]?.code}}<small>23:47 · LLUVIA LIGERA</small></span></div><div class="operator-callout"><span>OPERADOR / {{op.number}}</span><strong>{{op.name}}</strong><small>{{op.role.toUpperCase()}} <i/> {{loadout.dog?'ATLAS EN EQUIPO':'DESPLIEGUE EN SOLITARIO'}}</small></div><div class="stage-bottom-label"><span>PIXEL ART. NUEVA PERSPECTIVA.</span><span>CAM 03 <Target :size="13"/></span></div></div>
   <div class="stage-equipment"><button data-testid="stage-edit-operator" @click="tab='operators'"><Shield :size="24"/><span><small>ESPECIALIDAD</small><strong>{{op.perk}}</strong></span><ChevronRight :size="16"/></button><button data-testid="stage-edit-weapon" @click="tab='arsenal'"><Crosshair :size="24"/><span><small>ARMA PRINCIPAL</small><strong>{{weapon.title}}</strong></span><ChevronRight :size="16"/></button><button data-testid="stage-edit-companion" @click="tab='companion'"><PawPrint :size="24"/><span><small>COMPAÑERO</small><strong>{{loadout.dog?'Atlas · Pastor alemán':'Sin compañero'}}</strong></span><ChevronRight :size="16"/></button></div>
   <div class="transmission"><Radio :size="20"/><span><small>ÚLTIMA TRANSMISIÓN / CONTROL</small><q>Si puedes escucharme, aún hay una salida.</q></span><div class="radio-bars"><i/><i/><i/><i/><i/><i/><i/><i/><i/></div></div></section>
  </div>
  <footer class="lobby-footer"><span><span class="status-dot"/> UNA CIUDAD. TU ÚLTIMA GUARDIA.</span><span><Headphones :size="13"/> MEJOR CON AURICULARES</span><span>{{records.kills}} BAJAS <i/> {{records.wins}} EXTRACCIONES</span></footer>
  <div v-if="help" class="modal-backdrop" @click.self="help=false"><section class="dialog-panel help-panel" role="dialog" aria-modal="true" aria-labelledby="help-title"><header><span class="section-kicker">MANUAL DE CAMPO</span><button data-testid="help-close" class="icon-button" aria-label="Cerrar ayuda" @click="help=false"><X/></button></header><h2 id="help-title">Cada segundo cuenta<span>.</span></h2><div class="help-grid"><p><Crosshair/><strong>Movimiento y puntería</strong><span>WASD o flechas para moverte. Ratón y clic para apuntar y disparar. En móvil, dos sticks independientes.</span></p><p><Target/><strong>Armas y recarga</strong><span>1–8 para elegir arma, Q para alternar, R para recargar. Puedes desactivar el disparo automático en ajustes.</span></p><p><Zap/><strong>Tu plan B</strong><span>Espacio: pulso EMP. E: convocar apoyo si tienes una señal S. P o Escape: pausa.</span></p><p><Skull/><strong>Vuelve con vida</strong><span>Recoge XP y mejoras. Supera diez rondas, elimina al coloso y ve a Puerto Ceniza. Quédate 4 segundos en la extracción.</span></p></div><button data-testid="help-understood" class="primary wide" @click="help=false">ENTENDIDO. ESTOY LISTO. <ArrowRight :size="17"/></button></section></div>
 </section>
</template>
